$base = "Refined Courses\STATISTICS\Units\Unit 01"
function WriteFile($path,$content){$dir=Split-Path $path -Parent; if(!(Test-Path $dir)){New-Item -ItemType Directory -Force -Path $dir|Out-Null}; Set-Content -LiteralPath $path -Value $content -Encoding UTF8}
function HeaderBlock($lesson,$page){ "<div style='font-family: Arial, Helvetica, sans-serif; font-size: 18px; line-height: 1.75; color: #ffffff; max-width: 980px; margin: 0 auto 18px auto; background: #111827; border-radius: 12px; padding: 14px 18px;'><strong>STATISTICS | Unit 01 | Lesson $lesson</strong></div><div style='font-family: Arial, Helvetica, sans-serif; font-size: 18px; line-height: 1.75; color: #1f2933; max-width: 980px; margin: 0 auto 22px auto; background: #e8f4ff; border-left: 8px solid #2563eb; border-radius: 10px; padding: 24px;'><h1 style='font-size: 30px; margin-top: 0; margin-bottom: 12px;'>$page</h1></div>"}
function CardBlock($color,$title,$body){$map=@{gray='#f8fafc|#64748b';green='#ecfdf5|#059669';orange='#fff7ed|#ea580c';red='#fef2f2|#dc2626';purple='#f5f3ff|#7c3aed';blue='#e8f4ff|#2563eb'}; $a=$map[$color].Split('|'); "<div style='font-family: Arial, Helvetica, sans-serif; font-size: 18px; line-height: 1.75; color: #1f2933; max-width: 980px; margin: 0 auto 22px auto; border: 1px solid #d1d5db; border-radius: 10px; padding: 22px; background: $($a[0]); border-left: 6px solid $($a[1]);'><h2 style='font-size: 24px; margin-top: 0; margin-bottom: 10px;'>$title</h2>$body</div>"}
function GiftItem($id,$std,$q,$correct,$wrong,$letter){
  $choices=@{}; $i=0
  foreach($L in 'A','B','C','D'){ if($L -eq $letter){$choices[$L]=$correct}else{$choices[$L]=$wrong[$i];$i++} }
  $lines=@("::$id::","Question ID: $id","MLA Standard: $std","Question:",$q,"{")
  foreach($L in 'A','B','C','D'){ $prefix=if($L -eq $letter){'='}else{'~'}; $lines += "$prefix$L. $($choices[$L])" }
  $lines += "}"
  $lines -join "`r`n"
}
function WriteGift($path,$items){WriteFile $path (($items -join "`r`n`r`n")+"`r`n")}
function BuildGift($path,$lesson,$standard,$questions,$letters,$prefix){
  $items=@()
  for($i=1;$i -le $questions.Count;$i++){ $items += GiftItem "$prefix$('{0:D2}' -f $i)" $standard $questions[$i-1].q $questions[$i-1].c $questions[$i-1].w $letters[$i-1] }
  WriteGift $path $items
}

