$letters25=@('A','B','C','D','A','B','C','D','A','B','C','D','A','B','C','D','A','B','C','D','A','B','C','D','A')
$letters5=@('A','B','C','D','A')

$std5Html="<ul style='padding-left: 26px;'><li><strong>MLA.STAT.STQ.2</strong> - I can interpret a data display by explaining the variables, data type, quantities, context, and what can reasonably be concluded.</li></ul>"
$std6Html="<ul style='padding-left: 26px;'><li><strong>MLA.STAT.DVD.3</strong> - I can construct and interpret segmented bar graphs from relative frequency tables.</li></ul>"
